-- Migration 001 — baseline schema (PostgreSQL / Supabase).
-- Applied automatically by db.migrate() on startup; this file is the
-- authoritative SQL reference. Run manually with:
--   psql "$DATABASE_URL" -f migrations/001_baseline.sql
-- or via: npm run migrate

-- Schema isolation: tables live in `fraudshield`, not `public`.
-- Supabase's auto-generated Data API (PostgREST) only reaches `public`
-- so application data is never reachable via the anon or service_role key.
CREATE SCHEMA IF NOT EXISTS fraudshield;
SET search_path TO fraudshield;

REVOKE ALL ON SCHEMA fraudshield FROM PUBLIC;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')        THEN REVOKE ALL ON SCHEMA fraudshield FROM anon;        END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN REVOKE ALL ON SCHEMA fraudshield FROM authenticated; END IF;
END $$;

-- Schema version tracker (replaces PRAGMA user_version for portable migration tracking).
CREATE TABLE IF NOT EXISTS schema_meta (
    id      INTEGER PRIMARY KEY CHECK (id = 1),
    version INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS users (
    id                          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name                   VARCHAR(255) NOT NULL,
    email                       VARCHAR(255) NOT NULL UNIQUE,
    phone_number                VARCHAR(20),
    created_at                  TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    updated_at                  TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    avatar_url                  VARCHAR(255),
    email_high_risk_enabled     INTEGER NOT NULL DEFAULT 1,
    email_weekly_summary_enabled INTEGER NOT NULL DEFAULT 1,
    total_scans                 INTEGER NOT NULL DEFAULT 0,
    threats_neutralized         INTEGER NOT NULL DEFAULT 0,
    community_reports           INTEGER NOT NULL DEFAULT 0
);
ENABLE ROW LEVEL SECURITY ON users;
-- No permissive policies: the backend's service connection bypasses RLS;
-- the Supabase anon/authenticated roles are already revoked from the schema
-- and would see zero rows even if they somehow connected.
ALTER TABLE users  FORCE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS user_credentials (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
    password_hash VARCHAR(255) NOT NULL,  -- bcrypt cost 12
    created_at    TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    updated_at    TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);
ENABLE ROW LEVEL SECURITY ON user_credentials;
ALTER TABLE user_credentials FORCE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS identity_verifications (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id               BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    document_type         TEXT NOT NULL CHECK(document_type IN ('Aadhaar', 'PAN', 'DL', 'Passport')),
    document_number_hash  VARCHAR(255) NOT NULL,  -- bcrypt, never stored in clear
    full_name_on_doc      VARCHAR(255) NOT NULL,
    dob_on_doc            TEXT NOT NULL,
    verification_status   TEXT NOT NULL DEFAULT 'Pending' CHECK(verification_status IN ('Pending', 'Approved', 'Rejected')),
    created_at            TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);
ENABLE ROW LEVEL SECURITY ON identity_verifications;
ALTER TABLE identity_verifications FORCE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS support_tickets (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          BIGINT REFERENCES users(id) ON DELETE SET NULL,
    name             VARCHAR(255) NOT NULL,
    email            VARCHAR(255) NOT NULL,
    phone_number     VARCHAR(20),
    issue_description TEXT NOT NULL,
    ticket_status    TEXT NOT NULL DEFAULT 'Open' CHECK(ticket_status IN ('Open', 'In Progress', 'Closed')),
    created_at       TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);
ENABLE ROW LEVEL SECURITY ON support_tickets;
ALTER TABLE support_tickets FORCE ROW LEVEL SECURITY;

-- Every analysis (manual, screenshot, Gmail, SMS). `report` holds the full engine output as JSON.
CREATE TABLE IF NOT EXISTS detections (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    source     TEXT NOT NULL CHECK(source IN ('manual', 'screenshot', 'gmail', 'sms')),
    kind       TEXT NOT NULL CHECK(kind IN ('url', 'message')),
    sender     TEXT,
    subject    TEXT,
    target     TEXT NOT NULL,
    risk       INTEGER NOT NULL,
    verdict    TEXT NOT NULL CHECK(verdict IN ('legit', 'suspicious', 'malicious')),
    confidence INTEGER,
    summary    TEXT,
    report     TEXT NOT NULL,
    status     TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open', 'acknowledged', 'resolved', 'false_positive')),
    created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);
CREATE INDEX IF NOT EXISTS idx_detections_user_time ON detections(user_id, created_at DESC);
ENABLE ROW LEVEL SECURITY ON detections;
ALTER TABLE detections FORCE ROW LEVEL SECURITY;

-- One monitored Gmail inbox per user. `secret` = AES-256-GCM(App Password, DATA_ENCRYPTION_KEY).
CREATE TABLE IF NOT EXISTS gmail_accounts (
    user_id          BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    email            TEXT NOT NULL,
    secret           TEXT NOT NULL,
    enabled          INTEGER NOT NULL DEFAULT 1,
    status           TEXT NOT NULL DEFAULT 'connecting',
    last_error       TEXT,
    last_uid         BIGINT,
    uid_validity     TEXT,
    messages_scanned INTEGER NOT NULL DEFAULT 0,
    last_event_at    TEXT,
    created_at       TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);
ENABLE ROW LEVEL SECURITY ON gmail_accounts;
ALTER TABLE gmail_accounts FORCE ROW LEVEL SECURITY;

-- Paired Android/iOS devices. Only the SHA-256 of the device token is stored.
CREATE TABLE IF NOT EXISTS devices (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name             TEXT NOT NULL,
    platform         TEXT NOT NULL DEFAULT 'android',
    token_hash       TEXT NOT NULL UNIQUE,
    messages_received INTEGER NOT NULL DEFAULT 0,
    last_seen_at     TEXT,
    created_at       TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
);
ENABLE ROW LEVEL SECURITY ON devices;
ALTER TABLE devices FORCE ROW LEVEL SECURITY;

INSERT INTO schema_meta (id, version) VALUES (1, 1) ON CONFLICT (id) DO NOTHING;
